repo.donations.py:
"""Donation records."""


class Donation:
    def __init__(self, donor, pounds):
        self.donor = donor
        self.pounds = pounds

    def __repr__(self):
        return "Donation(%r, %r)" % (self.donor, self.pounds)


ROWS = [('noor', 6), ('noor', 36), ('mia', 23), ('pia', 14), ('noor', 40), ('mia', 9)]


def load_donations():
    """Yield the stored donations one at a time."""
    for donor, pounds in ROWS:
        yield Donation(donor, pounds)

repo.summary.py:
"""Summary of donations."""


class DonationSummary:
    def __init__(self, donations):
        self._donations = donations

    def count(self):
        """Return how many donations there are."""
        return sum(1 for _ in self._donations)

    def mean_pounds(self):
        """Return the mean pounds, or 0.0 when there are no donations."""
        total = sum(x.pounds for x in self._donations)
        n = self.count()
        return total / n if n else 0.0
